text:
.account-hub-thundermail-header {
  display: none;
  flex-direction: column;
  align-items: center;
  gap: calc(var(--space-base) * 2);

  & button {
    border-radius: 3px;
    background: transparent;
    border: 1px solid var(--color-primary-default);
    display: inline-flex;
    padding: calc(var(--space-base) + var(--space-step)) calc(var(--space-base) * 2);
    align-items: center;
    gap: var(--space-base);
    color: var(--color-primary-default);
    font-size: 1.153rem;
    font-weight: 500;

    & img {
      block-size: 20px;
      inline-size: 20px;
      content: var(--icon-thundermail-lg);
    }
  }

  & .account-hub-thundermail-divider {
    color: var(--color-text-secondary);
    text-align: center;
    font-size: 0.923rem;
    font-weight: 400;
    line-height: 100%;

    &::before,
    &::after {
      content: "";
      background: var(--color-surface-border);
      inline-size: 38px;
      block-size: 1px;
      display: inline-block;
      vertical-align: middle;
    }
  }

  & .account-hub-thundermail-title {
    color: var(--color-text-base);
    font-size: 1.7rem;
    font-weight: 400;
    margin-block: 0;
  }
}

/* stylelint-disable-next-line media-query-no-invalid */
@media -moz-pref("mail.accounthub.thundermail.enabled") {
  :host([hide-title-on-thundermail]) #accountHubHeaderTitle {
    display: none;
  }

  .account-hub-thundermail-header {
    display: flex;
  }
}
